partial class Alter
{
    bool showHiddenOptions;
    Profile ImportExternalTrainer(string file)
    {
        if (!File.Exists(file) || !Path.GetExtension(file).Equals(".exe", StringComparison.OrdinalIgnoreCase)) throw new InvalidOperationException("Select a Windows trainer EXE.");
        string filename = Path.GetFileNameWithoutExtension(file); string game = System.Text.RegularExpressions.Regex.Replace(filename, @"\s+v\d.*$", "", System.Text.RegularExpressions.RegexOptions.IgnoreCase); game = System.Text.RegularExpressions.Regex.Replace(game, @"\s+(?:Plus\s+\d+\s+)?Trainer(?:\s+Updated)?$", "", System.Text.RegularExpressions.RegexOptions.IgnoreCase);
        var options = FlingOptionExtractor.Extract(file); var profile = new Profile { id = Guid.NewGuid().ToString("N"), name = game, process = "External trainer", version = options.Count > 0 ? "FLiNG · " + options.Count + " detected options" : "External trainer", externalTrainer = file, sourcePage = "" };
        foreach (var option in options) profile.cheats.Add(new Feature { name = option.Name, category = option.Category, kind = "external", hotkey = option.Hotkey });
        MessageBox.Show(options.Count > 0 ? "Found " + options.Count + " options and hotkeys inside this FLiNG EXE. Review them before use; the EXE will launch only when you choose Launch. Alter cannot read cheat on/off states or rewrite the original trainer." : "No readable FLiNG option list was found in this EXE. An editable external profile was created; you can add its options manually. The EXE will launch only when you choose Launch.", "External trainer import");
        return profile;
    }
    void ExternalTrainer()
    {
        body.Children.Clear(); if (selected.cheats == null) selected.cheats = new List<Feature>();
        var scroll = new ScrollViewer { VerticalScrollBarVisibility = ScrollBarVisibility.Auto }; body.Children.Add(scroll); var page = new StackPanel { Margin = new Thickness(25, 18, 25, 30) }; scroll.Content = page;
        var heading = new Grid { Height = 155, Background = Brush("#170D2D") }; ApplyBanner(heading, selected); heading.ColumnDefinitions.Add(new ColumnDefinition()); heading.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(190) }); var title = new StackPanel { Margin = new Thickness(24, 20, 10, 0) }; title.Children.Add(Copy("EXTERNAL TRAINER", 10, AccentSoftHex)); var gameTitle = Copy(selected.name, 27, "#F5EEFC"); gameTitle.FontWeight = FontWeights.SemiBold; gameTitle.Margin = new Thickness(0, 4, 0, 4); title.Children.Add(gameTitle); title.Children.Add(Copy(selected.version + "  ·  " + selected.cheats.Count + " options", 12, "#AFA3C0")); title.Children.Add(Copy("Runs through the original trainer. Alter cannot read its on/off state.", 11, "#9588A8")); heading.Children.Add(title); var launch = ExternalButton("▶  Launch trainer", () => LaunchExternal(), true, 160); launch.VerticalAlignment = VerticalAlignment.Bottom; launch.Margin = new Thickness(0, 0, 20, 20); Grid.SetColumn(launch, 1); heading.Children.Add(launch); page.Children.Add(Surface(heading, new Thickness(0)));
        var bar = new Grid { Margin = new Thickness(0, 18, 0, 7) }; bar.ColumnDefinitions.Add(new ColumnDefinition()); bar.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto }); var barTitle = Copy("OPTIONS", 14, "#EAE1F6"); barTitle.FontWeight = FontWeights.SemiBold; barTitle.VerticalAlignment = VerticalAlignment.Center; bar.Children.Add(barTitle); var actions = new StackPanel { Orientation = Orientation.Horizontal }; var add = ExternalButton("＋  Add option", () => ExternalOptionEditor(null), true, 120); actions.Children.Add(add); var details = ExternalButton("Edit details", () => EditExternalDetails(), false, 110); details.Margin = new Thickness(0, 0, 0, 0); actions.Children.Add(details); var artwork = ExternalButton("Artwork", () => ArtworkEditor(), false, 95); actions.Children.Add(artwork); var source = ExternalButton("Change EXE", () => ChangeExternalPath(), false, 110); actions.Children.Add(source); var export = ExternalButton("Export", () => ExportProfile(), false, 80); actions.Children.Add(export); var hiddenButton = ExternalButton(showHiddenOptions ? "Hide hidden" : "Show hidden", () => { showHiddenOptions = !showHiddenOptions; ExternalTrainer(); }, false, 115); actions.Children.Add(hiddenButton); Grid.SetColumn(actions, 1); bar.Children.Add(actions); page.Children.Add(bar);
        var note = Copy("The EXE stays in its original location. Labels, categories and hotkeys are editable here.", 11, "#887B9B"); note.Margin = new Thickness(0, 0, 0, 7); page.Children.Add(note);
        foreach (var group in selected.cheats.Where(f => f.kind == "external" && (!f.hidden || showHiddenOptions)).GroupBy(f => String.IsNullOrWhiteSpace(f.category) ? "Other" : f.category))
        {
            var section = new StackPanel { Margin = new Thickness(0, 13, 0, 0) }; var groupTitle = Copy(group.Key.ToUpperInvariant(), 11, AccentSoftHex); groupTitle.FontWeight = FontWeights.SemiBold; groupTitle.Margin = new Thickness(2, 0, 0, 10); section.Children.Add(groupTitle);
            foreach (var f in group) { var row = new Grid { MinHeight = 47, Margin = new Thickness(0, 0, 0, 3) }; row.ColumnDefinitions.Add(new ColumnDefinition()); row.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(160) }); row.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(102) }); row.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(72) }); var label = Copy(f.name, 12, f.hidden ? "#746985" : "#EDE5F6"); label.VerticalAlignment = VerticalAlignment.Center; label.Margin = new Thickness(2, 0, 8, 0); row.Children.Add(label); var hot = Copy(f.hotkey, 11, "#A494BE"); hot.VerticalAlignment = VerticalAlignment.Center; hot.Margin = new Thickness(6, 0, 0, 0); Grid.SetColumn(hot, 1); row.Children.Add(hot); var fire = ExternalButton("Send key", () => SendExternalHotkey(f), false, 0); fire.Height = 31; fire.Margin = new Thickness(3, 4, 3, 4); fire.IsEnabled = !f.hidden; Grid.SetColumn(fire, 2); row.Children.Add(fire); var edit = ExternalButton("Edit", () => ExternalOptionEditor(f), false, 0); edit.Height = 31; edit.Margin = new Thickness(3, 4, 0, 4); Grid.SetColumn(edit, 3); row.Children.Add(edit); section.Children.Add(row); }
            page.Children.Add(Surface(section, new Thickness(15)));
        }
        if (selected.cheats.Count == 0) page.Children.Add(Copy("No options yet. Add the trainer's published hotkeys to control it from Alter.", 12, "#9B8DAD"));
    }
    Button ExternalButton(string label, Action action, bool primary, double width) { var button = Button(label, action, primary); button.MinWidth = 0; if (width > 0) button.Width = width; button.Height = 34; button.Margin = new Thickness(0, 0, 8, 0); button.Padding = new Thickness(8, 0, 8, 0); button.HorizontalContentAlignment = HorizontalAlignment.Center; button.VerticalContentAlignment = VerticalAlignment.Center; button.FontSize = 11; return button; }
    void EditExternalDetails() { var w = new Window { Title = "Edit trainer details", Width = 460, Height = 280, Owner = this, WindowStartupLocation = WindowStartupLocation.CenterOwner, Background = Brush("#0B0A1B"), Foreground = Ink }; StyleDialog(w); var p = new StackPanel { Margin = new Thickness(22) }; w.Content = p; p.Children.Add(Copy("Game name", 12, "#D7CBEB")); var name = new TextBox { Text = selected.name }; p.Children.Add(name); p.Children.Add(Copy("Version or description", 12, "#D7CBEB")); var version = new TextBox { Text = selected.version }; p.Children.Add(version); var save = ExternalButton("Save details", () => { if (String.IsNullOrWhiteSpace(name.Text)) { MessageBox.Show("Enter a game name."); return; } selected.name = name.Text.Trim(); selected.version = version.Text.Trim(); SaveProfile(selected); w.Close(); ExternalTrainer(); }, true, 120); save.Margin = new Thickness(0, 16, 0, 0); p.Children.Add(save); w.ShowDialog(); }
    void LaunchExternal() { try { if (!File.Exists(selected.externalTrainer)) throw new FileNotFoundException("Trainer EXE not found. Use Change EXE to locate it."); Process.Start(new ProcessStartInfo(selected.externalTrainer) { WorkingDirectory = Path.GetDirectoryName(selected.externalTrainer), UseShellExecute = true }); } catch (Exception ex) { MessageBox.Show(ex.Message, "Alter"); } }
    void ChangeExternalPath() { var d = new Microsoft.Win32.OpenFileDialog { Filter = "Windows trainer|*.exe" }; if (d.ShowDialog() != true) return; selected.externalTrainer = d.FileName; SaveProfile(selected); ExternalTrainer(); }
    void ExternalOptionEditor(Feature existing)
    {
        var w = new Window { Title = existing == null ? "Add external option" : "Edit external option", Width = 460, Height = 385, Owner = this, WindowStartupLocation = WindowStartupLocation.CenterOwner, Background = Brush("#0B0A1B"), Foreground = Ink }; StyleDialog(w);
        var p = new StackPanel { Margin = new Thickness(22) }; w.Content = p;
        p.Children.Add(Copy("Display name", 12, "#D7CBEB")); var name = new TextBox { Text = existing == null ? "" : existing.name }; p.Children.Add(name);
        p.Children.Add(Copy("Category", 12, "#D7CBEB")); var category = new TextBox { Text = existing == null ? "Other" : existing.category }; p.Children.Add(category);
        p.Children.Add(Copy("Original trainer hotkey", 12, "#D7CBEB"));
        string captured = existing == null ? "" : existing.hotkey; var keyRow = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 7, 0, 0) };
        var keyText = Copy(String.IsNullOrWhiteSpace(captured) ? "No key set" : captured, 13, "#ECE4FA"); keyText.Width = 205; keyText.VerticalAlignment = VerticalAlignment.Center; keyRow.Children.Add(keyText);
        bool capturing = false; var capture = ExternalButton("Change key", () => { }, false, 125); capture.Content = "Change key"; capture.Click += (s, e) => { capturing = true; capture.Content = "Press keys…"; capture.Focus(); }; keyRow.Children.Add(capture); p.Children.Add(keyRow);
        var keyNote = Copy("Press a key or combination. Esc cancels. Match the key used by the original EXE.", 11, "#9588A7"); keyNote.Margin = new Thickness(0, 4, 0, 0); p.Children.Add(keyNote);
        w.PreviewKeyDown += (s, e) => { if (!capturing) return; e.Handled = true; Key key = e.Key == Key.System ? e.SystemKey : e.Key; if (key == Key.Escape) { capturing = false; capture.Content = "Change key"; return; } if (key == Key.LeftCtrl || key == Key.RightCtrl || key == Key.LeftAlt || key == Key.RightAlt || key == Key.LeftShift || key == Key.RightShift || key == Key.LWin || key == Key.RWin) return; string value = CapturedHotkey(key, Keyboard.Modifiers); if (value == null) return; captured = value; keyText.Text = value; capturing = false; capture.Content = "Change key"; };
        var hidden = new CheckBox { Content = "Hide this option", IsChecked = existing != null && existing.hidden, Foreground = Ink, Margin = new Thickness(0, 15, 0, 0) }; p.Children.Add(hidden);
        var actions = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 15, 0, 0) }; var save = ExternalButton("Save option", () => { if (String.IsNullOrWhiteSpace(name.Text) || String.IsNullOrWhiteSpace(captured)) { MessageBox.Show("Enter a name and capture a hotkey."); return; } try { ParseHotkey(captured); } catch (Exception ex) { MessageBox.Show(ex.Message); return; } var f = existing ?? new Feature { kind = "external" }; f.name = name.Text.Trim(); f.category = category.Text.Trim(); f.hotkey = captured; f.hidden = hidden.IsChecked == true; if (existing == null) selected.cheats.Add(f); SaveProfile(selected); w.Close(); ExternalTrainer(); }, true, 120); actions.Children.Add(save);
        if (existing != null) { var remove = ExternalButton("Remove", () => { selected.cheats.Remove(existing); SaveProfile(selected); w.Close(); ExternalTrainer(); }, false, 95); actions.Children.Add(remove); }
        p.Children.Add(actions); w.ShowDialog();
    }
    string CapturedHotkey(Key key, ModifierKeys modifiers) { string main = null; if (key >= Key.NumPad0 && key <= Key.NumPad9) main = "Num " + (key - Key.NumPad0); else if (key == Key.Add) main = "Num +"; else if (key == Key.Subtract) main = "Num -"; else if (key == Key.Multiply) main = "Num *"; else if (key == Key.Divide) main = "Num /"; else if (key == Key.Decimal) main = "Num ."; else if (key == Key.PageUp) main = "PageUp"; else if (key == Key.PageDown) main = "PageDown"; else if (key == Key.Home) main = "Home"; else if (key == Key.End) main = "End"; else if (key == Key.Insert) main = "Insert"; else if (key == Key.Delete) main = "Delete"; else if (key >= Key.F1 && key <= Key.F24) main = "F" + (1 + key - Key.F1); else if (key >= Key.A && key <= Key.Z) main = key.ToString(); else if (key >= Key.D0 && key <= Key.D9) main = (key - Key.D0).ToString(); if (main == null) return null; string prefix = ""; if ((modifiers & ModifierKeys.Control) != 0) prefix += "Ctrl+"; if ((modifiers & ModifierKeys.Alt) != 0) prefix += "Alt+"; if ((modifiers & ModifierKeys.Shift) != 0) prefix += "Shift+"; return prefix + main; }
    [DllImport("user32.dll")] static extern void keybd_event(byte key, byte scan, uint flags, UIntPtr extra);
    const uint KeyRelease = 2;
    byte[] ParseHotkey(string text) { var parts = text.Replace("Num +", "NumPlus").Replace("num +", "NumPlus").Replace(" ", "").Split('+'); var keys = new List<byte>(); foreach (string raw in parts) { string p = raw.ToLowerInvariant(); if (p == "ctrl") keys.Add(0x11); else if (p == "alt") keys.Add(0x12); else if (p == "shift") keys.Add(0x10); else if (p == "pageup") keys.Add(0x21); else if (p == "pagedown") keys.Add(0x22); else if (p == "home") keys.Add(0x24); else if (p == "end") keys.Add(0x23); else if (p == "insert") keys.Add(0x2D); else if (p == "delete") keys.Add(0x2E); else if (p.StartsWith("num")) { string key = p.Substring(3); if (key == "plus") keys.Add(0x6B); else if (key.Length == 1 && key[0] >= '0' && key[0] <= '9') keys.Add((byte)(0x60 + key[0] - '0')); else if (key == ".") keys.Add(0x6E); else if (key == "-") keys.Add(0x6D); else if (key == "*") keys.Add(0x6A); else if (key == "/") keys.Add(0x6F); else throw new FormatException("Unsupported number-pad key: " + raw); } else if (p.Length == 1 && p[0] >= 'a' && p[0] <= 'z') keys.Add((byte)(0x41 + p[0] - 'a')); else if (p.Length == 1 && p[0] >= '0' && p[0] <= '9') keys.Add((byte)(0x30 + p[0] - '0')); else if (p.Length > 1 && p[0] == 'f') { int n; if (int.TryParse(p.Substring(1), out n) && n >= 1 && n <= 24) keys.Add((byte)(0x70 + n - 1)); else throw new FormatException("Unsupported function key: " + raw); } else throw new FormatException("Unsupported hotkey part: " + raw); } if (keys.Count == 0) throw new FormatException("Enter a hotkey."); return keys.ToArray(); }
    void SendExternalHotkey(Feature f) { try { if (f.hidden) return; string exe = Path.GetFileNameWithoutExtension(selected.externalTrainer); if (Process.GetProcessesByName(exe).Length == 0) throw new InvalidOperationException("Launch the original trainer first."); var keys = ParseHotkey(f.hotkey); foreach (byte key in keys) keybd_event(key, 0, 0, UIntPtr.Zero); for (int i = keys.Length - 1; i >= 0; i--) keybd_event(keys[i], 0, KeyRelease, UIntPtr.Zero); } catch (Exception ex) { MessageBox.Show(ex.Message, "Alter hotkey"); } }
}
